282	// raceFixture is one concurrency scenario: the parent chain already ingested,
283	// the height under contention, and two candidate contents that both extend the
284	// tip (so either may legitimately win).
285	type raceFixture struct {
286		name    string
287		parents []Block
288		winner  Block // arbitrary pinning for post-race classification; either may win
289		loser   Block
290	}
291	
292	// validateRaceFixture is a setup-time oracle check: the two candidates are at
293	// the same next height over the same parent hash, each individually accepted
294	// on a fresh copy of the parent chain, each is rejected once the other is
295	// installed, and the two genuinely differ in content. A fixture that fails
296	// these would make the race assertions meaningless.
297	func validateRaceFixture(t *testing.T, f raceFixture) {
298		t.Helper()
299		height := int64(len(f.parents)) + 1
300		if f.winner.Height != height || f.loser.Height != height {
301			t.Fatalf("fixture %q: candidates must target next height %d", f.name, height)
302		}
303		tipHash := f.parents[len(f.parents)-1].Hash
304		if f.winner.Parent != tipHash || f.loser.Parent != tipHash {
305			t.Fatalf("fixture %q: both candidates must parent the tip hash %q", f.name, tipHash)
306		}
307		if f.winner.Hash == "" || f.loser.Hash == "" {
308			t.Fatalf("fixture %q: candidate hashes must be non-empty", f.name)
309		}
310		if sameBlock(f.winner, f.loser) {
311			t.Fatalf("fixture %q: the two candidates must be different content", f.name)
312		}
313		build := func() *Index {
314			index := New()
315			for _, b := range f.parents {
316				if err := index.Append(b); err != nil {
317					t.Fatalf("fixture %q setup append at %d: %v", f.name, b.Height, err)
318				}
319			}
320			return index
321		}
322		first, second := build(), build()
323		if err := first.Append(cloneCandidate(f.winner)); err != nil {
324			t.Fatalf("fixture %q: winner candidate must be accepted on its own: %v", f.name, err)
325		}
326		if err := second.Append(cloneCandidate(f.loser)); err != nil {
327			t.Fatalf("fixture %q: loser candidate must be accepted on its own: %v", f.name, err)
328		}
329		if err := first.Append(cloneCandidate(f.loser)); err == nil {
330			t.Fatalf("fixture %q: loser content must be rejected after winner is installed", f.name)
331		}
332		if err := second.Append(cloneCandidate(f.winner)); err == nil {
333			t.Fatalf("fixture %q: winner content must be rejected after loser is installed", f.name)
334		}
335	}
