381	// TestConcurrentAppendIdenticalContentAllSucceeds: many independent copies of
382	// one candidate race at the next height. Every call must succeed, the tip
383	// advances exactly one height, and the winning block's transactions are stored
384	// once — in original order, keeping in-block duplicates and positions — with
385	// no occurrence gained from the repeated submissions.
386	func TestConcurrentAppendIdenticalContentAllSucceeds(t *testing.T) {
387		const submissions = 16
388		parents := []Block{{Height: 1, Hash: "p1", Parent: "genesis", Txs: []string{"g1", "g2"}}}
389	
390		cases := []struct {
391			name  string
392			block Block
393		}{
394			{
395				name:  "txs with an in-block duplicate",
396				block: Block{Height: 2, Hash: "c2", Parent: "p1", Txs: []string{"a", "b", "a", "a", "b"}},
397			},
398			{
399				name:  "nil tx list",
400				block: Block{Height: 2, Hash: "c2", Parent: "p1", Txs: nil},
401			},
402			{
403				name:  "with timestamp",
404				block: Block{Height: 2, Hash: "c2", Parent: "p1", Txs: []string{"a", "b", "a"}, Time: intptr(42)},
405			},
406		}
407		for _, tc := range cases {
408			t.Run(tc.name, func(t *testing.T) {
409				index := New()
410				for _, b := range parents {
411					if err := index.Append(b); err != nil {
412						t.Fatalf("setup append at %d: %v", b.Height, err)
413					}
414				}
415	
416				// Every submission gets its OWN independent backing data, so
417				// acceptance cannot be relying on slice/pointer identity.
418				candidates := make([]Block, submissions)
419				for i := range candidates {
420					candidates[i] = cloneCandidate(tc.block)
421				}
422				results := raceAppendAtHeight(t, index, candidates)
423				for i, r := range results {
424					if r.err != nil {
425						t.Fatalf("identical-content call #%d failed: %v", i, r.err)
426					}
427					if !sameBlock(r.block, tc.block) {
428						t.Fatalf("call #%d submitted mutated content %+v", i, r.block)
429					}
430				}
431	
432				assertStoredWinner(t, index, 1, tc.block)
433				assertWinnerQuery(t, index, tc.block, Block{})
434				assertWinnerSnapshot(t, index, parents, tc.block)
435	
436				// Explicit duplicate accounting for the in-block duplicate rule:
437				// "a" occurs twice in the block (positions 0 and 2 for the first
438				// fixture) regardless of the 16 identical submissions, and its
439				// hits keep those exact positions.
440				if len(tc.block.Txs) > 0 {
441					counts := map[string]int{}
442					positions := map[string][]int{}
443					for pos, tx := range tc.block.Txs {
444						counts[tx]++
445						positions[tx] = append(positions[tx], pos)
446					}
447					for tx, wantCount := range counts {
448						page, err := index.QueryTxs(TxQuery{From: 2, To: 2, TxIDs: []string{tx}})
449						if err != nil {
450							t.Fatalf("query %q failed: %v", tx, err)
451						}
452						if page.TotalMatches != int64(wantCount) || int64(len(page.Hits)) != int64(wantCount) {
453							t.Fatalf("tx %q occurrences=%d (matches=%d), want block-internal count %d after %d submissions",
454								tx, len(page.Hits), page.TotalMatches, wantCount, submissions)
455						}
456						var gotPositions []int
457						for _, hit := range page.Hits {
458							gotPositions = append(gotPositions, hit.Position)
459						}
460						if !reflect.DeepEqual(gotPositions, positions[tx]) {
461							t.Fatalf("tx %q positions=%v, want original in-block positions %v",
462								tx, gotPositions, positions[tx])
463						}
464					}
465				}
466			})
467		}
468	}
