470	// TestConcurrentAppendIdenticalNilAndEmptyTxsBothWin: a missing tx list and an
471	// explicit empty list are the SAME content, so a race mixing both forms must
472	// accept every call and store exactly one empty block.
473	func TestConcurrentAppendIdenticalNilAndEmptyTxsBothWin(t *testing.T) {
474		const each = 8
475		parents := []Block{{Height: 1, Hash: "p1", Parent: "genesis", Txs: []string{"g1"}}}
476		index := New()
477		if err := index.Append(parents[0]); err != nil {
478			t.Fatal(err)
479		}
480		winner := Block{Height: 2, Hash: "c2", Parent: "p1"} // nil txs, no time
481		candidates := make([]Block, 0, 2*each)
482		for i := 0; i < each; i++ {
483			b := cloneCandidate(winner)
484			candidates = append(candidates, b)
485			empty := cloneCandidate(winner)
486			empty.Txs = []string{}
487			candidates = append(candidates, empty)
488		}
489		results := raceAppendAtHeight(t, index, candidates)
490		for i, r := range results {
491			if r.err != nil {
492				t.Fatalf("equivalent nil/empty-tx call #%d failed: %v", i, r.err)
493			}
494		}
495		assertStoredWinner(t, index, 1, winner)
496		page, err := index.QueryTxs(TxQuery{From: 2, To: 2})
497		if err != nil {
498			t.Fatal(err)
499		}
500		if len(page.Hits) != 0 || page.TotalMatches != 0 || page.MatchedBlocks != 0 {
501			t.Fatalf("empty winning block must yield no occurrences: %+v", page)
502		}
503		assertWinnerSnapshot(t, index, parents, winner)
504	}
