45	func queryRetainedBlocks() []Block {
46		return []Block{
47			{Height: 1, Hash: "h1", Parent: "g", Txs: []string{"x", "x"}},
48			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"y"}},
49		}
50	}
