82		}
83	
84		// Observable state 2: the reorg has completed and is visible through
85		// queries and the index, while the earlier export is still open.
86		assertExportStillRunning(t, done)
87		if index.Tip != 4 || index.Blocks[2].Hash != "new-b" || index.Blocks[3].Hash != "new-c" {
88			t.Fatalf("reorg not observable on the index: %+v", index.Blocks)
89		}
90		for _, gone := range []string{"old-b", "old-c"} {
91			if _, ok := index.ByHash[gone]; ok {
92				t.Fatalf("reorged-away hash %s still indexed", gone)
93			}
94		}
95		if got := index.Blocks[2].Txs; !reflect.DeepEqual(got, []string{"new-tx", "", "new-tx"}) {
96			t.Fatalf("new block txs=%q", got)
97		}
98		page, err := index.QueryTxs(TxQuery{})
99		if err != nil || page.TotalMatches != 7 || page.ToHeight != 4 {
100			t.Fatalf("query after reorg: page=%+v err=%v", page, err)
101		}
102		page, err = index.QueryTxs(TxQuery{TxIDs: []string{"old-tx"}})
103		if err != nil || page.TotalMatches != 0 {
104			t.Fatalf("old tx still queryable after reorg: %+v err=%v", page, err)
105		}
106		page, err = index.QueryTxs(TxQuery{TxIDs: []string{"new-tx"}})
107		if err != nil {
108			t.Fatal(err)
109		}
110		wantNewHits := []TxHit{
111			{Height: 2, BlockHash: "new-b", TxID: "new-tx", Position: 0},
112			{Height: 2, BlockHash: "new-b", TxID: "new-tx", Position: 2},
113			{Height: 4, BlockHash: "new-d", TxID: "new-tx", Position: 0},
114		}
115		if !reflect.DeepEqual(page.Hits, wantNewHits) {
116			t.Fatalf("new-tx hits=%v, want %v", page.Hits, wantNewHits)
117		}
118	
119		// The sink finishes receiving: the export ends successfully and its
120		// bytes describe exactly the old main chain selected when writing began.
121		rest, err := io.ReadAll(pr)
122		if err != nil {
123			t.Fatalf("draining the export failed: %v", err)
124		}
125		if err := <-done; err != nil {
126			t.Fatalf("export after reorg failed: %v", err)
127		}
128		raw := string(first[0]) + string(rest)
129		if raw != wantOldSnapshot {
130			t.Fatalf("pinned export=%s\nwant=%s", raw, wantOldSnapshot)
131		}
132		// Explicit leakage guards: the document must name no replacement hash,
133		// transaction, or the new tip, and must keep the old height cap.
134		for _, leaked := range []string{"new-b", "new-c", "new-d", "new-tx", `"tip":4`} {
135			if strings.Contains(raw, leaked) {
136				t.Fatalf("old snapshot leaks replacement content %q: %s", leaked, raw)
137			}
138		}
139		var timedDoc struct {
140			Version int64 `json:"version"`
141			Tip     int64 `json:"tip"`
142			Blocks  []struct {
143				Height    int64           `json:"height"`
144				Hash      string          `json:"hash"`
145				Parent    string          `json:"parent"`
146				Txs       []string        `json:"txs"`
147				Timestamp json.RawMessage `json:"timestamp"`
148			} `json:"blocks"`
149		}
150		if err := json.Unmarshal([]byte(raw), &timedDoc); err != nil {
151			t.Fatalf("pinned snapshot does not parse: %v", err)
152		}
153		if timedDoc.Version != 2 || timedDoc.Tip != 3 || len(timedDoc.Blocks) != 3 {
154			t.Fatalf("pinned snapshot shape: %+v", timedDoc)
155		}
156		wantTimes := []string{"null", "0", "1700000000"}
157		for i, block := range timedDoc.Blocks {
158			if got := string(block.Timestamp); got != wantTimes[i] {
159				t.Fatalf("block %d timestamp=%s, want %s", i+1, got, wantTimes[i])
160			}
161			if i > 0 && block.Parent != timedDoc.Blocks[i-1].Hash {
162				t.Fatalf("pinned snapshot breaks the parent link at height %d", block.Height)
163			}
164		}
165	
166		// The old snapshot restores into a separate index: old-chain txs are
167		// queryable there, including duplicates, the empty id, and their order;
168		// missing/zero/real timestamps come back as distinct values.
169		restored := New()
170		if err := restored.Restore(strings.NewReader(raw)); err != nil {
171			t.Fatalf("restore of pinned snapshot failed: %v", err)
172		}
173		if restored.Blocks[1].Time != nil {
174			t.Fatalf("height 1 time=%v, want missing", restored.Blocks[1].Time)
175		}
176		if restored.Blocks[2].Time == nil || *restored.Blocks[2].Time != 0 {
177			t.Fatalf("height 2 time=%v, want 0", restored.Blocks[2].Time)
178		}
179		if restored.Blocks[3].Time == nil || *restored.Blocks[3].Time != 1700000000 {
180			t.Fatalf("height 3 time=%v, want 1700000000", restored.Blocks[3].Time)
181		}
182		page, err = restored.QueryTxs(TxQuery{})
183		if err != nil || page.TotalMatches != 6 || page.ToHeight != 3 {
184			t.Fatalf("restored old-chain query: page=%+v err=%v", page, err)
185		}
186		page, err = restored.QueryTxs(TxQuery{TxIDs: []string{"old-tx"}})
187		if err != nil {
188			t.Fatal(err)
189		}
190		wantOldHits := []TxHit{
191			{Height: 2, BlockHash: "old-b", TxID: "old-tx", Position: 1},
192			{Height: 3, BlockHash: "old-c", TxID: "old-tx", Position: 0},
193		}
194		if !reflect.DeepEqual(page.Hits, wantOldHits) {
195			t.Fatalf("old-tx hits on restored index=%v, want %v", page.Hits, wantOldHits)
196		}
197		page, err = restored.QueryTxs(TxQuery{TxIDs: []string{"new-tx"}})
198		if err != nil || page.TotalMatches != 0 {
199			t.Fatalf("restored old index sees replacement txs: %+v err=%v", page, err)
200		}
201		if again := exportString(t, restored); again != raw {
202			t.Fatalf("re-export of restored old snapshot differs:\n%s\n%s", again, raw)
203		}
204	
205		// Restoring the old chain elsewhere leaves the current main chain alone.
206		page, err = index.QueryTxs(TxQuery{TxIDs: []string{"after"}})
207		if err != nil {
208			t.Fatal(err)
209		}
210		wantAfter := []TxHit{{Height: 3, BlockHash: "new-c", TxID: "after", Position: 0}}
211		if !reflect.DeepEqual(page.Hits, wantAfter) {
212			t.Fatalf("after-tx on current index=%v, want %v", page.Hits, wantAfter)
213		}
214	
215		// A second export after the reorg reflects only the new, fully untimed
216		// chain: version 1, no timestamp field anywhere, tip and hashes new.
217		wantNewSnapshot := `{"version":1,"tip":4,"blocks":[` +
218			`{"height":1,"hash":"old-a","parent":"genesis","txs":["dup",""]},` +
219			`{"height":2,"hash":"new-b","parent":"old-a","txs":["new-tx","","new-tx"]},` +
220			`{"height":3,"hash":"new-c","parent":"new-b","txs":["after"]},` +
221			`{"height":4,"hash":"new-d","parent":"new-c","txs":["new-tx"]}` +
222			`]}`
223		if rawNew := exportString(t, index); rawNew != wantNewSnapshot {
224			t.Fatalf("post-reorg export=%s\nwant=%s", rawNew, wantNewSnapshot)
225		}
226		if strings.Contains(exportString(t, index), "timestamp") {
227			t.Fatalf("post-reorg snapshot still carries a timestamp field")
228		}
229	}
230	
231	// gateWriteOutcome is what a blockingGateWriter returns from its one blocked
232	// Write call.
233	type gateWriteOutcome struct {
234		accepted int
235		err      error
236	}
237	
238	// blockingGateWriter silently accepts up to prefix bytes of the first write,
239	// records them, signals entered, and then blocks until the test releases it
240	// with a fixed return value. Export performs exactly one Write, which is all
241	// this writer needs to support.
242	type blockingGateWriter struct {
243		prefix   int
244		entered  chan struct{}
245		release  chan gateWriteOutcome
246		received bytes.Buffer
247	}
248	
249	func (w *blockingGateWriter) Write(p []byte) (int, error) {
250		n := w.prefix
251		if n > len(p) {
252			n = len(p)
253		}
254		w.received.Write(p[:n])
255		close(w.entered)
256		out := <-w.release
257		if out.accepted > len(p) {
258			out.accepted = len(p)
259		}
260		return out.accepted, out.err
261	}
262	
263	// startTimedExportReorgedMidStream builds an old chain whose only non-missing
264	// timestamp sits on the block about to be reorged away, starts an export into
265	// a gate blocked after 16 bytes, performs the reorg while the export is open,
266	// and verifies every observable state along the way. The post-reorg chain is
267	// entirely untimed, so a fresh export switches from version 2 to version 1.
268	func startTimedExportReorgedMidStream(t *testing.T) (*Index, string, *blockingGateWriter, <-chan error) {
269		t.Helper()
270		index := chain(t,
271			Block{Height: 1, Hash: "old-a", Parent: "genesis", Txs: []string{"old-a-tx"}},
272			Block{Height: 2, Hash: "old-b", Parent: "old-a", Txs: []string{"old-b-tx"}, Time: intptr(1700000000)},
273		)
274		wantOld := exportString(t, index)
275		if !strings.Contains(wantOld, `"version":2`) || len(wantOld) <= 17 {
276			t.Fatalf("test setup: old snapshot too small or not v2: %s", wantOld)
277		}
278	
279		writer := &blockingGateWriter{
280			prefix:  16,
281			entered: make(chan struct{}),
282			release: make(chan gateWriteOutcome),
283		}
284		done := make(chan error, 1)
285		go func() {
286			done <- index.Export(writer)
287		}()
288		<-writer.entered
289		if got := writer.received.String(); got != wantOld[:16] {
290			t.Fatalf("in-flight prefix=%q, want old-chain prefix %q", got, wantOld[:16])
291		}
292		assertExportStillRunning(t, done)
293	
294		dropped, err := index.Reorg([]Block{
295			{Height: 2, Hash: "new-b", Parent: "old-a", Txs: []string{"new-b-tx", "", "new-b-tx"}},
296		})
297		if err != nil {
298			t.Fatalf("reorg while export blocked refused: %v", err)
299		}
300		if !reflect.DeepEqual(dropped, []int64{2}) {
301			t.Fatalf("dropped=%v, want [2]", dropped)
302		}
303		assertExportStillRunning(t, done)
304		return index, wantOld, writer, done
305	}
306	
307	// requireCurrentChainIsReplacement verifies the reorg survived and the
308	// current main chain is the untimed replacement, including through a fresh
309	// export that must be version 1 with no timestamp residue.
310	func requireCurrentChainIsReplacement(t *testing.T, index *Index) {
311		t.Helper()
312		if index.Tip != 2 {
313			t.Fatalf("tip=%d, want 2", index.Tip)
314		}
315		block := index.Blocks[2]
316		if block.Hash != "new-b" || block.Parent != "old-a" || block.Time != nil {
317			t.Fatalf("height 2=%+v, want new-b without a timestamp", block)
318		}
319		if !reflect.DeepEqual(block.Txs, []string{"new-b-tx", "", "new-b-tx"}) {
320			t.Fatalf("replacement txs=%q", block.Txs)
321		}
322		if _, ok := index.ByHash["old-b"]; ok {
323			t.Fatal("reorged-away hash old-b still indexed")
324		}
325		page, err := index.QueryTxs(TxQuery{TxIDs: []string{"old-b-tx"}})
326		if err != nil || page.TotalMatches != 0 {
327			t.Fatalf("old tx still queryable: %+v err=%v", page, err)
328		}
329		page, err = index.QueryTxs(TxQuery{TxIDs: []string{"new-b-tx"}})
330		if err != nil || page.TotalMatches != 2 {
331			t.Fatalf("new tx matches=%d err=%v, want 2", page.TotalMatches, err)
332		}
333		raw := exportString(t, index)
334		want := `{"version":1,"tip":2,"blocks":[` +
335			`{"height":1,"hash":"old-a","parent":"genesis","txs":["old-a-tx"]},` +
336			`{"height":2,"hash":"new-b","parent":"old-a","txs":["new-b-tx","","new-b-tx"]}` +
337			`]}`
338		if raw != want {
339			t.Fatalf("post-reorg export=%s\nwant=%s", raw, want)
340		}
341		if strings.Contains(raw, "timestamp") {
342			t.Fatalf("post-reorg snapshot still carries a timestamp field: %s", raw)
343		}
344	}
345	
346	func TestExportSinkFailureAfterReorgKeepsReorg(t *testing.T) {
347		t.Run("sink returns concrete error", func(t *testing.T) {
348			index, _, writer, done := startTimedExportReorgedMidStream(t)
349			boom := errors.New("sink disk full")
350			writer.release <- gateWriteOutcome{accepted: 16, err: boom}
351			if err := <-done; !errors.Is(err, boom) {
352				t.Fatalf("export err=%v, want the sink error", err)
353			}
354			// The completed reorg stands; the failed export changed nothing.
355			requireCurrentChainIsReplacement(t, index)
356		})
357	
358		t.Run("sink accepts only some bytes with no error", func(t *testing.T) {
359			index, wantOld, writer, done := startTimedExportReorgedMidStream(t)
360			// Honest short write: the sink keeps only the 16 buffered bytes of
361			// the document and returns nil instead of an error.
362			writer.release <- gateWriteOutcome{accepted: 16, err: nil}
363			if 16 >= len(wantOld) {
364				t.Fatalf("test setup: accepted bytes must be below %d", len(wantOld))
365			}
366			if err := <-done; !errors.Is(err, io.ErrShortWrite) {
367				t.Fatalf("export err=%v, want io.ErrShortWrite", err)
368			}
369			requireCurrentChainIsReplacement(t, index)
370		})
371	}
