	// has not returned; h4 is already visible to a lock-holder.
	func() {
		index.mu.Lock()
		defer index.mu.Unlock()
		if index.Tip != 4 || index.ByHash["h4"] != 4 {
			t.Fatalf("parked append intermediate state: tip=%d h4=%v, want tip 4 with h4 stored",
				index.Tip, index.ByHash["h4"])
		}
	}()

	type reorgOutcome struct {
		dropped []int64
		err     error
	}
	reorgDone := make(chan reorgOutcome, 1)
	waitForBlocked(t, func() {
		dropped, err := index.Reorg(f.branch)
		reorgDone <- reorgOutcome{dropped, err}
	}

