		t.Fatalf("r2 parent %q does not chain onto retained h1 %q", stored.Parent, index.Blocks[1].Hash)
	}
	if _, ok := index.Blocks[3]; ok {
		t.Fatal("height 3 (h3) still readable after the interleaving")
